package com.ejemplo.msa.controller;
import com.ejemplo.msa.dto.EntityADto; import com.ejemplo.msa.service.EntityAService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/entity-a") public class EntityAController { private final EntityAService service; public EntityAController(EntityAService service){this.service=service;} @GetMapping public List<EntityADto> listar(){return service.listar();} @GetMapping("/{id}") public ResponseEntity<EntityADto> buscar(@PathVariable Long id){return service.buscar(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<EntityADto> crear(@Valid @RequestBody EntityADto dto){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(dto));} @PutMapping("/{id}") public ResponseEntity<EntityADto> actualizar(@PathVariable Long id,@Valid @RequestBody EntityADto dto){return service.actualizar(id,dto).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){return service.eliminar(id)?ResponseEntity.noContent().build():ResponseEntity.notFound().build();} @PostMapping("/by-ids") public List<EntityADto> byIds(@RequestBody List<Long> ids){return service.findAllByIds(ids);} }
